"""Real Chromium: explicit side blocking, quote length independence and curated contact sheets."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import base64, re
ROOT=Path(__file__).resolve().parents[1]
JS=(ROOT/'dist/frontend.js').read_text('utf8').rsplit('export {',1)[0].replace('export function ', 'function ')+'''\nwindow.t={CAST_PRESENTATION_ENTRIES,CAST_PRESENTATION_CSS,CAST_PRESENTATION_SIDE_CSS,castPresentationTemplate};'''
ART='data:image/png;base64,'+base64.b64encode((ROOT/'tests/fixtures/cast-portrait.png').read_bytes()).decode()
WORLD=base64.b64decode(re.search(r'--world:\s*url\("data:image/jpeg;base64,([^"\)]+)"\)',(ROOT/'docs/cast-layout-sources/curated-cards.html').read_text('utf8'))[1])
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 page=browser.new_page(viewport={'width':1160,'height':900})
 page.route('**/api/v1/images/world1',lambda route:route.fulfill(content_type='image/jpeg',body=WORLD))
 page.set_content('<!doctype html><html><head><base href="http://cast.local/"></head><body style="margin:0;background:#15131a;color:#eee;font:14px system-ui"><main id="sheet"></main></body></html>')
 page.add_script_tag(content=JS)
 page.evaluate('''()=>{let css=document.createElement('style');css.textContent=t.CAST_PRESENTATION_CSS+'\\n'+t.CAST_PRESENTATION_SIDE_CSS;document.head.append(css)}''')
 page.evaluate('''()=>{window.make=(entry,side,art,quote)=>t.castPresentationTemplate(entry.id,{key:'shoto-joy',src:art,name:'Shoto',label:'joy',dialogue:quote,color:'#72B9FF',side,background:{id:'world1',name:'Evening walkway'},crop:{enabled:false,x:50,y:20,zoom:1}},s=>s)}''')
 errors=page.evaluate('''async art=>{const results=[];const entries=t.CAST_PRESENTATION_ENTRIES.filter(e=>e.origin==='atelier');for(const entry of entries)for(const width of [520,420,320])for(const side of ['auto','left','right']){let last=null,shortHeight=null;for(const [index,quote] of ['“Short.”','“Tell Yaoyorozu she owes five thousand yen. You dropped that straight into Mina’s lap like you were handing her a press release. Half of our old class is going to be losing their minds before we even get out of boots.”','“'+('The plaza was quiet, but the night shift had no intention of calling it a day. '.repeat(6))+'”'].entries()){const host=document.querySelector('#sheet');host.innerHTML=`<div style="width:${width}px">${make(entry,side,art,quote)}</div>`;const stage=host.querySelector('.stage,.stage-canvas,.corner-cinematic,.angle-cinematic'),actor=stage.querySelector('.actor,.stage-actor,.corner-sprite,.angle-sprite'),image=actor.querySelector('img'),q=stage.querySelector('[data-swarm-cast-dialogue]');await image.decode();const a=actor.getBoundingClientRect(),s=stage.getBoundingClientRect(),r=q.getBoundingClientRect();const x=a.x+a.width/2-s.x-s.width/2;if((side==='auto'?false:side==='left'?x>=0:x<=0)||getComputedStyle(q).direction!=='ltr'||r.x<s.x-5||r.right>s.right+5||r.bottom>s.bottom+5)results.push({id:entry.id,width,side,x,quoteBounds:[r.x-s.x,r.right-s.right,r.bottom-s.bottom]});if(entry.composition==='scene'){const ir=image.getBoundingClientRect(),cs=getComputedStyle(image),gap=stage.clientHeight-actor.offsetTop-image.offsetTop-image.offsetHeight,expected={'vn-hero':0,'afterglow-cinema':0,'postcard-original':25,'rainbound-platform':0,'memory-filmstrip':22,'afterglow-letterbox':38,'comic-establishing-redux':22,'postcard-rebellion':34}[entry.id],scale=Math.min(image.clientWidth/image.naturalWidth,image.clientHeight/image.naturalHeight);if(Math.abs(gap-expected)>2||!cs.objectPosition.includes('100%')||cs.objectFit!=='contain')results.push({id:entry.id,width,side,gap,expected,fit:cs.objectFit,position:cs.objectPosition});if(last!==null&&(Math.abs(gap-last.gap)>2||Math.abs(scale-last.scale)>.01))results.push({id:entry.id,width,side,gap,scale,last});last={gap,scale};if(index===0)shortHeight=stage.offsetHeight;if(index===1&&width===520&&Math.abs(stage.offsetHeight-shortHeight)>2)results.push({id:entry.id,side,unnecessaryGrowth:stage.offsetHeight-shortHeight});if(stage.querySelector('.postcard-date'))results.push({id:entry.id,obsoleteSlogan:true});}}}return results}''',ART)
 assert not errors,errors[:30]
 for family in ('scene','overlap','panel'):
  page.evaluate('''({family,art})=>{const entries=t.CAST_PRESENTATION_ENTRIES.filter(e=>e.origin==='atelier'&&e.composition===family);document.querySelector('#sheet').innerHTML=`<div style="padding:18px;display:grid;gap:18px"><h1 style="font-size:23px;margin:0">Cast Atelier · ${family} · Stage left / right</h1>${entries.map(e=>`<section style="border:1px solid #423849;border-radius:10px;padding:12px;background:#1d1922"><h2 style="font-size:15px;margin:0 0 10px">${e.name}</h2><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">${['left','right'].map(side=>`<div style="min-width:0"><p style="margin:0 0 6px;font-size:11px;color:#a99fb1">${side.toUpperCase()}</p>${make(e,side,art,'“We could kiss in the middle of the plaza and they would thank us for the market share increase.”')}</div>`).join('')}</div></section>`).join('')}</div>`}''',{'family':family,'art':ART})
  page.wait_for_function('[...document.images].every(i=>i.complete)');page.wait_for_timeout(200)
  page.screenshot(path=str(ROOT/f'test-results/cast-blocking-{family}.png'),full_page=True)
 page.evaluate('''art=>{const entries=t.CAST_PRESENTATION_ENTRIES.filter(e=>e.composition==='scene');const quotes=['“You really don’t give a single shit, do you?”','“Tell Yaoyorozu she owes five thousand yen. You dropped that straight into Mina’s lap like you were handing her a press release. Half of our old class is going to be losing their minds before we even get out of boots.”'];document.querySelector('#sheet').innerHTML=`<div style="padding:18px;display:grid;gap:18px"><h1 style="font-size:22px;margin:0">Scene grounding · short vs. long dialogue</h1>${entries.map(e=>`<section style="border:1px solid #423849;padding:12px"><h2 style="font-size:15px;margin:0 0 10px">${e.name}</h2><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:start">${quotes.map((quote,i)=>`<div><p style="margin:0 0 6px;font-size:11px;color:#a99fb1">${i?'LONG':'SHORT'}</p>${t.castPresentationTemplate(e.id,{key:'shoto-joy',src:art,name:'Shoto',label:'neutral',dialogue:quote,color:'#ffcc00',side:'right',crop:{enabled:false,x:50,y:20,zoom:1}},s=>s)}</div>`).join('')}</div></section>`).join('')}</div>`}''',ART)
 page.wait_for_function('[...document.images].every(i=>i.complete)')
 page.screenshot(path=str(ROOT/'test-results/cast-grounding-dialogue.png'),full_page=True)
 print('CAST CURATED BLOCKING PASS: 20 looks × three sides × three widths × three quote lengths; frame-relative image bottom, stable rendered scale, readable unmirrored text')
 browser.close()
